/* === Step 6: 渲染函数 === */
function renderVars(data) {
  // 更新顶部观测核心信息
  $("#m-target-name").text(data.targetName);
  $("#m-target-bar").css("width", _.clamp(data.pleasure, 0, 100) + "%");

  // 矩阵渲染核心算法
  const fillMatrix = ($container, obj) => {
    $container.empty();
    // 过滤隐藏变量并展平对象
    const entries = Object.entries(obj).filter(([k]) => !k.startsWith('_') && !k.startsWith('$'));

    // 强制生成 25 个格子的循环
    for (let i = 0; i < 25; i++) {
      const [key, val] = entries[i] || ["--", "--"]; // 不足 25 个则用占位符

      const $item = $(`
        <div class="matrix-item">
          <div class="m-label" title="${key}">${key}</div>
          <div class="m-value" title="${val}">${val}</div>
        </div>
      `);
      $container.append($item);
    }
  };

  // 执行身体与着装的矩阵填充
  fillMatrix($("#m-grid-body"), data.body);
  fillMatrix($("#m-grid-outfit"), data.outfit);
}
