          // 固定生成 25 个单元格 (5x5)
          for (let i = 0; i < 25; i++) {
            const [k, v] = entries[i] || ["--", "--"];
            const $item = $(`
              <div class="matrix-item">
                <div class="m-label">${k}</div>
                <div class="m-value" title="${v}">${v}</div>
              </div>
            `);
            $el.append($item);
          }
        };

        fillMatrix($("#m-grid-body"), _.get(sd, "目标.身体"));
        fillMatrix($("#m-grid-outfit"), _.get(sd, "目标.着装"));
      };

      refresh();
      eventOn(Mvu.events.VARIABLE_INITIALIZED, refresh);
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refresh);
    }
    $(errorCatched(init));
  </script>
