    for (let i = 0; i < 25; i++) {
      const [key, val] = entries[i] || ["--", "--"]; // 不足 25 个则用占位符

      const $item = $(`
        <div class="matrix-item">
          <div class="m-label" title="${key}">${key}</div>
          <div class="m-value" title="${val}">${val}</div>
        </div>
      `);
      $container.append($item);
    }
  };

  // 执行身体与着装的矩阵填充
  fillMatrix($("#m-grid-body"), data.body);
  fillMatrix($("#m-grid-outfit"), data.outfit);
}
